{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    by_id = {}
    positions = {}
    for position, node in enumerate(nodes):
        if not isinstance(node, dict) or any(field not in node for field in fields):
            raise ValueError("invalid node")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("invalid parent")
        if not isinstance(symbol, str):
            raise ValueError("invalid symbol")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("invalid depth")
        if not isinstance(removable, bool):
            raise ValueError("invalid removable flag")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("invalid utility")
        by_id[node_id] = node
        positions[node_id] = position

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("tree must have one root at depth zero")
    root_id = roots[0]["id"]
    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id:
                raise ValueError("parent does not exist")
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("inconsistent depth")
            children[parent].append(node["id"])

    state = {node_id: 0 for node_id in by_id}
    def visit(node_id):
        if state[node_id] == 1:
            raise ValueError("cycle in tree")
        if state[node_id] == 2:
            return
        state[node_id] = 1
        for child_id in children[node_id]:
            visit(child_id)
        state[node_id] = 2
    visit(root_id)
    if any(value != 2 for value in state.values()):
        raise ValueError("disconnected node")

    required = set(required_symbols)
    if not required.issubset({node["symbol"] for node in nodes}):
        raise ValueError("required symbol is absent")

    retained = set(by_id)
    removed = []
    candidates = sorted(
        (node for node in nodes if node["removable"]),
        key=lambda node: (-node["depth"], node["id"])
    )
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        remaining_symbols = {by_id[other_id]["symbol"] for other_id in retained if other_id != node_id}
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained)
    }"}
